describe('Element Manager - Add and Delete Elements', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  it('should add and delete elements successfully', () => {
    // Verify initial state
    cy.get('[data-testid="added-manually"]').should('not.exist');
    cy.get('[data-testid="added-manually"]').should('have.length', 0);

    // Add first element
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="added-manually"]').should('have.length', 1);
    cy.get('[data-testid="added-manually"]').first().should('be.visible');

    // Add second element
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="added-manually"]').should('have.length', 2);
    cy.get('[data-testid="added-manually"]').should('all').be.visible();

    // Delete first element
    cy.get('[data-testid="added-manually"]').first().click();
    cy.get('[data-testid="added-manually"]').should('have.length', 1);
    cy.get('[data-testid="added-manually"]').should('not.contain', 'first');

    // Delete second element
    cy.get('[data-testid="added-manually"]').click();
    cy.get('[data-testid="added-manually"]').should('have.length', 0);
    cy.get('[data-testid="added-manually"]').should('not.exist');
  });

  it('should handle edge case of deleting the last element', () => {
    // Add first element
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="added-manually"]').should('have.length', 1);

    // Add second element
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="added-manually"]').should('have.length', 2);

    // Delete first element
    cy.get('[data-testid="added-manually"]').first().click();
    cy.get('[data-testid="added-manually"]').should('have.length', 1);

    // Delete the last remaining element
    cy.get('[data-testid="added-manually"]').click();
    cy.get('[data-testid="added-manually"]').should('have.length', 0);
    cy.get('[data-testid="added-manually"]').should('not.exist');

    // Verify no error state is displayed
    cy.get('[data-testid="flash-messages"]').should('not.exist');
  });
});
